  // ==== COURRIERS FIDÈLES AUX MODÈLES DE L'ÉTUDE (étude 15/10 : « les courriers de sortie reprennent exactement la même disposition à la
  // ligne près, l'espacement près, les tableaux aussi ; vraiment les mêmes, les couleurs, les espacements ») ====
  // Un courrier de « Constitution de dossier » est décrit LIGNE À LIGNE (`documentCourrierVente`, `documentCourrierSuccession` dans commun/) :
  // chaque chaîne est un paragraphe Times 11 sans espacement, '' une ligne vide, **gras**, __souligné__, et des tableaux. Le même document
  // donne le Word (modèle de l'appel de fonds, corps refait paragraphe par paragraphe), le PDF/A (mêmes positions, relevées sur les originaux :
  // première ligne à 139,6 pt, interligne 12,65 pt, colonne de droite jusqu'à 309 pt), l'aperçu et le texte de l'email. La page du
  // questionnaire d'assainissement est celle du Word de l'étude, reprise telle quelle (tableau bordeaux, cases ❑).

  var LIGNES_FIDELE = { depart: 139.6, pas: 12.65, colonneDroite: 300.1, finColonneDroite: 309, gauche: 141.75, droite: 566.93, basPremiere: 771, bas: 787.9, haut: 28.35, ligneDate: 9 };

  // Pure : « **gras** __souligné__ » → [{ t, b, u }].
  function runsLigneCourrier(texte) {
    const runs = [];
    let b = false;
    let u = false;
    String(texte || '').split(/(\*\*|__)/).forEach(m => {
      if (m === '**') { b = !b; return; }
      if (m === '__') { u = !u; return; }
      if (m) runs.push({ t: m, b, u });
    });
    return runs;
  }

  // Pure : les lignes de la colonne « Nos Réf » de l'en-tête : intitulé du dossier, référence, responsable (comme les courriers de l'étude).
  function refLignesCourrier(d) {
    if (!d) return [];
    return [`Nos Réf : ${libelleDossierAffiche(d).replace(/^(VTE|SUCC) - /, '$1 ')}`, String(d.referenceAuthentic || '').trim(),
      d.responsable ? 'Dossier suivi par :' : '', String(d.responsable || '').trim(), 'office.gossart@notaires.fr', '0254786170'].filter(Boolean);
  }

  // ---- Word ----

  var RPR_FIDELE = '<w:rFonts w:ascii="Times New Roman" w:hAnsi="Times New Roman" w:cs="Times New Roman"/>';

  function xmlRunsFidele(runs) {
    return runs.map(r => `<w:r><w:rPr>${RPR_FIDELE}${r.b ? '<w:b/>' : ''}<w:sz w:val="22"/><w:szCs w:val="22"/>${r.u ? '<w:u w:val="single"/>' : ''}</w:rPr><w:t xml:space="preserve">${xmlTexteWord(r.t)}</w:t></w:r>`).join('');
  }

  function xmlParagrapheFidele(texte, jc, autresPpr) {
    // Sans contrôle des veuves et orphelines, comme les modèles de l'étude : la page se remplit jusqu'en bas (pas de ligne repoussée).
    return `<w:p><w:pPr>${autresPpr || ''}<w:widowControl w:val="false"/><w:spacing w:before="0" w:after="0" w:line="240" w:lineRule="auto"/><w:jc w:val="${jc || 'both'}"/><w:rPr>${RPR_FIDELE}<w:sz w:val="22"/><w:szCs w:val="22"/></w:rPr></w:pPr>${xmlRunsFidele(runsLigneCourrier(texte))}</w:p>`;
  }

  // Pure : un tableau du courrier (parcelles) avec la mise en forme du modèle de l'étude : largeurs fixes, filets noirs de 0,5 pt, en-tête grisé.
  function xmlTableauFidele(tab) {
    const bord = (n) => `<w:${n} w:val="single" w:sz="4" w:space="0" w:color="000000"/>`;
    const bords = `<w:tcBorders>${['top', 'left', 'bottom', 'right'].map(bord).join('')}</w:tcBorders>`;
    const largeur = tab.grille.reduce((s, x) => s + x, 0);
    const lignes = tab.lignes.map(r => {
      let col = 0;
      return `<w:tr>${r.cellules.map(c => {
        const span = c.span || 1;
        const w = tab.grille.slice(col, col + span).reduce((s, x) => s + x, 0);
        col += span;
        const jc = c.jc === 'right' ? 'right' : c.jc === 'center' ? 'center' : 'both';
        return `<w:tc><w:tcPr><w:tcW w:w="${w}" w:type="dxa"/>${span > 1 ? `<w:gridSpan w:val="${span}"/>` : ''}${bords}${c.fond ? `<w:shd w:val="clear" w:color="auto" w:fill="${c.fond}"/>` : ''}</w:tcPr>`
          + `<w:p><w:pPr><w:keepNext/><w:keepLines/><w:widowControl w:val="false"/><w:spacing w:before="0" w:after="0" w:line="240" w:lineRule="auto"/><w:jc w:val="${jc}"/><w:rPr>${RPR_FIDELE}<w:sz w:val="22"/><w:szCs w:val="22"/></w:rPr></w:pPr>${xmlRunsFidele(runsLigneCourrier(c.texte))}</w:p></w:tc>`;
      }).join('')}</w:tr>`;
    }).join('');
    return `<w:tbl><w:tblPr><w:tblW w:w="${largeur}" w:type="dxa"/><w:tblInd w:w="${tab.ind || 0}" w:type="dxa"/><w:tblLayout w:type="fixed"/>`
      + '<w:tblCellMar><w:top w:w="34" w:type="dxa"/><w:left w:w="108" w:type="dxa"/><w:bottom w:w="23" w:type="dxa"/><w:right w:w="108" w:type="dxa"/></w:tblCellMar></w:tblPr>'
      + `<w:tblGrid>${tab.grille.map(g => `<w:gridCol w:w="${g}"/>`).join('')}</w:tblGrid>${lignes}</w:tbl>`;
  }

  // Pure : le corps Word d'un courrier fidèle : lignes vides avant l'adresse, adresse, lignes vides jusqu'à « Blois, le … » (10e ligne),
  // puis chaque ligne du document ; « Me … » à droite, tampon et signature si pré-signé ; la page du questionnaire d'assainissement.
  function xmlCorpsCourrierFidele(doc, signatureXml) {
    const p = [];
    const vide = () => p.push(xmlParagrapheFidele(''));
    for (let i = 0; i < doc.adresseDebut; i++) vide();
    doc.adresse.forEach(l => p.push(xmlParagrapheFidele(l)));
    const blancs = Math.max(1, LIGNES_FIDELE.ligneDate - doc.adresseDebut - doc.adresse.length);
    for (let i = 0; i < blancs; i++) vide();
    p.push(xmlParagrapheFidele(doc.date));
    doc.lignes.forEach(l => { if (typeof l === 'string') p.push(xmlParagrapheFidele(l)); else p.push(xmlTableauFidele(l)); });
    for (let i = 0; i < (doc.blancsSignature || 0); i++) vide();
    p.push(xmlParagrapheFidele(doc.signature, 'right', '<w:keepNext/>'));
    if (signatureXml) p.push(signatureXml);
    if (doc.questionnaire) {
      // Une ligne vide en tête de page 2, comme dans le modèle (paragraphe vide après le saut) ; « saut avant » : même rendu dans Word et LibreOffice.
      p.push(xmlParagrapheFidele('', 'both', '<w:pageBreakBefore/>'));
      p.push(QUESTIONNAIRE_ASSAINISSEMENT_XML.replace('{QREF}', xmlTexteWord(doc.questionnaire.references)).replace('{QADR}', xmlTexteWord(doc.questionnaire.adresseImmeuble)));
    }
    return p.join('');
  }

  // Le .docx sur le papier à en-tête de l'office (modèle de l'appel de fonds) ; « Nos Réf » de l'en-tête sur plusieurs lignes.
  async function docxCourrierFidele(doc, d, options) {
    await chargerModeleAppelFonds();
    const zip = new window.PizZip(afBase64VersOctets(window.APPEL_FONDS_MODELE.docxB64));
    const ref = refLignesCourrier(d);
    Object.keys(zip.files).filter(n => /^word\/(header|footer)\d*\.xml$/.test(n)).forEach(n => {
      const x = zip.file(n).asText();
      if (!x.includes('{ref}')) return;
      const lignes = ref.length ? ref : ['Nos Réf : '];
      // « Nos Réf : {ref} » devient les lignes de la colonne, séparées par des retours à la ligne dans le même paragraphe.
      zip.file(n, x.replace('Nos Réf : {ref}', lignes.map(xmlTexteWord).join('</w:t><w:br/><w:t xml:space="preserve">')));
    });
    const modeleXml = zip.file('word/document.xml').asText();
    const xml = documentXmlCourrierAgent(modeleXml, xmlCorpsCourrierFidele(doc, options && options.signe ? paragrapheSignatureModele(modeleXml) : ''));
    if (!xml) throw new Error('modèle de l’office illisible');
    zip.file('word/document.xml', xml);
    return zip.generate({ type: 'blob', mimeType: 'application/vnd.openxmlformats-officedocument.wordprocessingml.document' });
  }

  // ---- PDF (appelé par genererPdfAAppelFonds, qui fournit les outils de dessin) ----

  // Dessine le courrier ligne à ligne aux positions relevées sur les originaux (Times = Liberation Serif, mêmes chasses).
  function composerPdfCourrierFidele(doc, o) {
    const L = LIGNES_FIDELE;
    let y = L.depart;
    const bas = () => (o.numero() === 1 ? L.basPremiere : L.bas);
    const saut = () => { o.nouvellePage(); y = L.haut; };
    const colonne = () => (o.numero() === 1 && y < L.finColonneDroite ? { x: L.colonneDroite, largeur: L.droite - L.colonneDroite } : { x: L.gauche, largeur: L.droite - L.gauche });
    const ligneSimple = (texte, x, jc) => {
      const runs = runsLigneCourrier(texte);
      const largeur = L.droite - x;
      const lignes = runs.length ? lignesSegmentsPdfA(runs, largeur, (t, st) => o.mesurer(t, st)) : [];
      lignes.forEach(li => { if (y + L.pas > bas()) saut(); o.dessinerLigne(li, x, largeur, jc || 'both', y); y += L.pas; });
      if (!lignes.length) y += L.pas;
    };
    const paragraphe = (texte, jc) => {
      if (y + L.pas > bas()) saut();
      const c = colonne();
      const runs = runsLigneCourrier(texte);
      if (!runs.length) { y += L.pas; return; }
      const lignes = lignesSegmentsPdfA(runs, c.largeur, (t, st) => o.mesurer(t, st));
      lignes.forEach(li => { if (y + L.pas > bas()) saut(); o.dessinerLigne(li, c.x, c.largeur, jc || 'both', y); y += L.pas; });
    };
    // Adresse et date : colonne de droite, positions fixes.
    y = L.depart + doc.adresseDebut * L.pas;
    doc.adresse.forEach(l => ligneSimple(l, L.colonneDroite));
    y = Math.max(y + L.pas, L.depart + L.ligneDate * L.pas);
    ligneSimple(doc.date, L.colonneDroite);
    doc.lignes.forEach(l => { if (typeof l === 'string') paragraphe(l); else tableauPdfFidele(l, o, () => y, (v) => { y = v; }, bas, saut); });
    y += (doc.blancsSignature || 0) * L.pas;
    if (y + L.pas > bas()) saut();
    const runs = runsLigneCourrier(doc.signature);
    const li = lignesSegmentsPdfA(runs, L.droite - L.gauche, (t, st) => o.mesurer(t, st))[0];
    if (li) o.dessinerLigne(li, L.gauche, L.droite - L.gauche, 'right', y);
    y += L.pas;
    if (o.signe) {
      const T = TAMPON_PDFA;
      if (y + T.bloc > bas()) saut();
      o.image('tampon', T.x, y + T.decalage, T.largeur, T.hauteur);
      o.image('signature', T.x + (T.largeur - T.signatureLargeur) / 2, y + T.decalage + (T.hauteur - T.signatureHauteur) / 2, T.signatureLargeur, T.signatureHauteur);
      y += T.bloc;
    }
    if (doc.questionnaire) { o.nouvellePage(); questionnairePdfFidele(doc.questionnaire, o); }
  }

  // Un tableau du courrier : cellules à la taille du modèle (twips / 20), texte à 5,4 pt du filet, rangées de 16 pt (une ligne).
  function tableauPdfFidele(tab, o, getY, setY, bas, saut) {
    const L = LIGNES_FIDELE;
    const x0 = L.gauche + 0.35;
    const largeurs = tab.grille.map(w => w / 20);
    const marge = 5.4;
    let y = getY();
    tab.lignes.forEach(r => {
      let col = 0;
      const cellules = r.cellules.map(c => {
        const span = c.span || 1;
        const x = x0 + largeurs.slice(0, col).reduce((s, v) => s + v, 0);
        const w = largeurs.slice(col, col + span).reduce((s, v) => s + v, 0);
        col += span;
        const runs = runsLigneCourrier(c.texte);
        const lignes = runs.length ? lignesSegmentsPdfA(runs, w - 2 * marge, (t, st) => o.mesurer(t, st)) : [];
        return { c, x, w, lignes };
      });
      const n = Math.max(1, ...cellules.map(c => c.lignes.length));
      const h = n * L.pas + 3.35;
      if (y + h > bas()) { saut(); y = L.haut; }
      cellules.forEach(({ c, x, w, lignes }) => {
        if (c.fond) o.page().drawRectangle({ x, y: o.H - y - h, width: w, height: h, color: o.hex(c.fond) });
        lignes.forEach((li, k) => o.dessinerLigne(li, x + marge, w - 2 * marge, c.jc === 'right' ? 'right' : c.jc === 'center' ? 'center' : 'left', y + 2.15 + k * L.pas));
      });
      // Filets : le haut et les séparations de la rangée, puis les côtés.
      o.trait(x0, y, x0 + largeurs.reduce((s, v) => s + v, 0), y, 0.5);
      cellules.forEach(({ x }) => o.trait(x, y, x, y + h, 0.5));
      const fin = x0 + largeurs.reduce((s, v) => s + v, 0);
      o.trait(fin, y, fin, y + h, 0.5);
      y += h;
      o.trait(x0, y, fin, y, 0.5);
    });
    setY(y + 0.45);
  }

  // La page du questionnaire, aux positions relevées sur le Word de l'étude (page 2) : textes, filets, bandeaux bordeaux, cases ❑.
